-- Phase 4F Pluto small-moon closure using independently validated published PLU060 dynamics.
-- Post-PLU060 state is explicit propagated estimate, never direct JPL authority.
BEGIN;
UPDATE loom_solar.curated_cohort_member SET final_outcome='QUALIFIED_PROPAGATED', reason='Direct PLU060 through native endpoint; validated published six-body-model continuation thereafter, explicitly non-direct.' WHERE body_id IN ('NIX','HYDRA','KERBEROS','STYX');
DO $$ DECLARE b integer; q integer; BEGIN SELECT count(*) INTO b FROM loom_solar.body; SELECT count(*) INTO q FROM loom_solar.ephemeris_coverage WHERE status='QUALIFIED'; IF b<>110 OR q<>128 THEN RAISE EXCEPTION 'Phase4F Pluto closure expected 110 bodies/128 qualified coverage rows, got %/%',b,q; END IF; END $$;
COMMIT;
